{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In male Wistar rats, [18F]5a crossed the BBB rapidly with an initial brain uptake of 3.67 %ID after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In monkey PET imaging, (S)-[18F]OF-Me-NB1 showed fast and high brain uptake with peak SUV of 3.0–4.5 within 15 minutes.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In mice, nor-BNI was detected in both brain and serum from 0.75 to 48 h after subcutaneous administration, demonstrating systemic CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved direct in-vivo systemic administration records demonstrate BBB penetration and brain uptake across rodents and nonhuman primates, with no evidence of inadequate CNS access. The overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No quantitative unbound brain-to-plasma ratios or functional CNS target engagement data were provided, but direct brain uptake after systemic administration is sufficient for a pass."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

